function validate([access_times]) {
  if (!Array.isArray(access_times) || access_times.length < 1 || access_times.length > 100) return 'access_times needs 1 to 100 entries.';
  for (const entry of access_times) {
    if (!Array.isArray(entry) || entry.length !== 2) return 'Each entry is [name, time].';
    const [name, time] = entry;
    if (typeof name !== 'string' || !/^[a-z]{1,10}$/.test(name)) return 'Each name has 1 to 10 lowercase letters.';
    if (typeof time !== 'string' || !/^([01][0-9]|2[0-3])[0-5][0-9]$/.test(time)) return 'Each time is four digits from "0000" to "2359".';
  }
  return null;
}

