function findHighAccessEmployees(access_times) {
  const entries = access_times.map(([name, time]) => [name, Number(time.slice(0, 2)) * 60 + Number(time.slice(2))]);
  entries.sort((x, y) => (x[0] < y[0] ? -1 : x[0] > y[0] ? 1 : x[1] - y[1]));

  const result = [];
  for (let i = 2; i < entries.length; i++) {
    const [name, minutes] = entries[i];
    if (entries[i - 2][0] !== name) {
      continue;
    }
    if (minutes - entries[i - 2][1] >= 60) {
      continue;
    }
    if (result[result.length - 1] !== name) {
      result.push(name);
    }
  }
  return result;
}

