function findHighAccessEmployees(access_times) {
  // For every access, count that employee's accesses in the 60-minute window starting there.
  const toMinutes = (t) => parseInt(t.slice(0, 2), 10) * 60 + parseInt(t.slice(2, 4), 10);
  const found = new Set();
  for (const [name, start] of access_times) {
    const from = toMinutes(start);
    let inside = 0;
    for (const [other, time] of access_times) {
      const at = toMinutes(time);
      if (other === name && at >= from && at < from + 60) inside++;
    }
    if (inside >= 3) found.add(name);
  }
  return [...found];
}

