function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const n = size === 'large' ? 100 : 1 + pick(12);
  const pool = size === 'large'
    ? Array.from({ length: 4 + pick(20) }, () => Array.from({ length: 1 + pick(10) }, () => letters[pick(3)]).join(''))
    : ['a', 'b', 'ab', 'ba', 'c'].slice(0, 1 + pick(4));
  // Times cluster around a few centres so that windows of three are sometimes, but not always, found.
  const centres = Array.from({ length: 1 + pick(4) }, () => pick(1440));
  const spread = [20, 45, 70, 180][pick(4)];
  const format = (m) => String(Math.floor(m / 60)).padStart(2, '0') + String(m % 60).padStart(2, '0');
  return [Array.from({ length: n }, () => {
    const minute = Math.min(1439, Math.max(0, centres[pick(centres.length)] + pick(2 * spread + 1) - spread));
    return [pool[pick(pool.length)], format(minute)];
  })];
}
